/**
 * Schema descriptions the docs say differently: two quote the Turkish interface, and the schema asks for a GitHub user
 * name where the store takes any name the author wants to be credited by.
 */
const REWORDED = {
  "author": "How you want to be credited: your name or your GitHub user name.",
  "contributes.actions[].verb": "A job's label in the ⇧ panel: \"↵ <verb> · ⌘C <verb> and copy\", such as \"Download\". Without it a job says \"Start\".",
  "contributes.actions[].failTitle": "A failed job's title, such as \"Couldn't download the video\"; a variant's own wins.",
};

/**
 * The reference for the schema: a table per object, each object's section right after the one it is first met in
 * (depth first), and a shared definition (`accepts`) once, under its own name.
 */
function manifestReference(schema, example) {
  const defs = schema.$defs ?? {};
  const resolve = (node) => (node?.$ref ? defs[node.$ref.split("/").at(-1)] : node);
  const refName = (node) => node?.$ref?.split("/").at(-1);
  const seen = new Map(); // ref name or path → section title
  const used = new Set();
  const titles = [];
  const out = [];

  const isObject = (node) => {
    const target = resolve(node);
    return target?.type === "object" && target.properties !== undefined;
  };
  const link = (title) => `[\`${title}\`](#${slug(`\`${title}\``)})`;

  /** The title of the section for the object `node` met at `path`, and whether this is the first time. */
  function titleFor(node, path) {
    const key = refName(node) ?? path;
    if (seen.has(key)) return { title: seen.get(key), first: false };
    const title = refName(node) === "accepts" ? "accepts" : path;
    seen.set(key, title);
    return { title, first: true };
  }

  /** The type column for `node` at `path`; objects met for the first time are added to `children`. */
  function typeOf(node, path, children) {
    if (refName(node) === "localeKey") return "[locale key](localization.md)";
    if (isObject(node)) {
      const { title, first } = titleFor(node, path);
      if (first) children.push({ title, node: resolve(node) });
      return `object, see ${link(title)}`;
    }
    if (node.const !== undefined) return `\`${JSON.stringify(node.const)}\``;
    if (node.enum) return `one of ${node.enum.map((value) => `\`${JSON.stringify(value)}\``).join(", ")}`;
    if (node.type === "array") {
      const items = node.items ?? {};
      if (isObject(items)) {
        const { title, first } = titleFor(items, `${path}[]`);
        if (first) children.push({ title, node: resolve(items) });
        return `list of objects, see ${link(title)}`;
      }
      return `list${node.minItems ? ` (at least ${node.minItems})` : ""} of ${typeOf(items, `${path}[]`, children)}`;
    }
    if (node.type === "string") {
      if (node.pattern) return `string matching \`${node.pattern}\``;
      return node.minLength ? "non-empty string" : "string";
    }
    return node.type ?? "any";
  }

  function row(sectionTitle, object, name, property, children) {
    const key = sectionTitle === "" ? name : `${sectionTitle}.${name}`;
    let required = (object.required ?? []).includes(name) ? "yes" : "";
    const condition = object.if?.properties;
    if (!required && condition && (object.then?.required ?? []).includes(name)) {
      const [field, value] = Object.entries(condition)[0];
      required = `when \`${field}\` is \`${JSON.stringify(value.const)}\``;
    }
    const type = typeOf(property, key, children);
    const own = Object.hasOwn(REWORDED, key) ? REWORDED[key] : (property.description ?? resolve(property)?.description ?? "");
    if (Object.hasOwn(REWORDED, key)) used.add(key);
    const note = NOTES[key];
    if (note !== undefined) used.add(key);
    const text = [own, note].filter((part) => part && part !== defs.localeKey?.description).join(" ");
    return `| \`${name}\` | ${type} | ${required} | ${text.replaceAll("|", "\\|")} |`;
  }

  function section(title, node) {
    titles.push(title === "" ? "Top level" : `\`${title}\``);
    out.push(title === "" ? "## Top level" : `## \`${title}\``, "");
    if (title === "accepts") out.push("Used by actions, detectors and capture rules.", "");
    out.push("| Field | Type | Required | What it does |", "|---|---|---|---|");
    const children = [];
    for (const [name, property] of Object.entries(node.properties)) out.push(row(title, node, name, property, children));
    out.push("");
    if (node.additionalProperties === false) out.push("No other fields: the store rejects any it does not know ([`unknownField`](errors.md#unknownfield)).", "");
    for (const child of children) section(child.title, child.node);
  }
  section("", schema);

  for (const key of [...Object.keys(NOTES), ...Object.keys(REWORDED)]) {
    if (!used.has(key)) throw new Error(`tools/docs.mjs: the note for "${key}" matches no field in schema/manifest.schema.json`);
  }

  return [
    GENERATED_NOTE("schema/manifest.schema.json"),
    "",
    "# Manifest reference",
    "",
    "`manifest.json` sits at the root of an extension's folder, next to `src/` and `locales/`. This page lists every field [the schema](../schema/manifest.schema.json) allows.",
    "",
    "Every text a person reads (names, titles, keywords, tags) is a key into `locales/<language>.json`, never the text itself; see [Localization](localization.md). Run `npm run validate -- <id>` after each change: it names the field, what was expected and how to fix it ([every message](errors.md)).",
    "",
    "Sections: " + titles.map((title) => `[${title}](#${slug(title)})`).join(" · ")
      + " · [Rules beyond the schema](#rules-beyond-the-schema) · [A complete example](#a-complete-example)",
    "",
    ...out,
    "## Rules beyond the schema",
    "",
    "`npm run validate` also checks what a schema cannot say:",
    "",
    "- `id` equals the extension's folder name.",
    "- `locales/<defaultLocale>.json` exists and holds every key the manifest uses; `locales/en.json` exists and holds them all too.",
    "- A `keywords` key's value is a list of strings in the locale file: `\"reverse.keywords\": [\"reverse\", \"flip\"]`.",
    "- `captureRules` need the `capture` permission; `exec` needs `requires.tools`, and `requires.tools` needs `exec`.",
    "- Ids are unique within their list (actions, variants of one action, detectors, capture rules, sources, actions of one source, preferences).",
    "- A `secret` preference has no `default`; a `folder` default starts with `~`; a `choice` has `options`.",
    "- `targetsOnly` needs at least one entry in `targets`.",
    "- A source has one or two actions. A `secret` action needs `\"sensitive\": true` on its source and has no `copyTitle` or `copied`, and an extension with one cannot ask for `network`.",
    "- `accepts.pattern` compiles as an ICU regular expression, the kind the app uses.",
    "- README.md and CHANGELOG.md exist, and, once built, so does `index.js`.",
    "",
    "## A complete example",
    "",
    `The manifest of [Download Video](../${path.posix.dirname(EXAMPLE_MANIFEST)}), which uses most fields:`,
    "",
    "```json",
    example.trimEnd(),
    "```",
    "",
  ].join("\n");
}

// ---------------------------------------------------------------------------------------------------------------
// docs/api.md

/** The text of a `/** … *\/` comment, without its stars. */
function commentText(raw) {
  const body = raw.trim().replace(/^\/\*\*/, "").replace(/\*\/$/, "");
  const lines = body.split("\n").map((line) => line.replace(/^\s*\* ?/, "").replace(/\s+$/, ""));
  while (lines.length > 0 && lines[0].trim() === "") lines.shift();
  while (lines.length > 0 && lines.at(-1).trim() === "") lines.pop();
  if (lines.length > 0) lines[0] = lines[0].trimStart();
  // A line that is not part of a list ends it, as in the source; Markdown needs a blank line to see that.
  for (let index = lines.length - 1; index > 0; index--) {
    const inList = /^(\s*- |\s{2,}\S)/.test(lines[index - 1]);
    if (inList && /^[^\s-]/.test(lines[index])) lines.splice(index, 0, "");
  }
  return lines.join("\n");
}

/** Reads index.d.ts with the TypeScript compiler's API and returns its declarations in source order. */
function readDeclarations(file) {
  const api = new API({ cwd: path.dirname(file) });
  try {
    const snapshot = api.updateSnapshot({ openFiles: [file] });
    const project = snapshot.getDefaultProjectForFile(file);
    const source = project?.program.getSourceFile(file);
    if (!source) throw new Error(`tools/docs.mjs: TypeScript could not read ${file}`);
    const text = source.text;

    /** A node's own text without its comment, its later lines moved left as far as its first. */
    const code = (node) => {
      const start = node.getStart();
      const column = start - (text.lastIndexOf("\n", start - 1) + 1);
      return text.slice(start, node.end).split("\n").map((line, index) => (index === 0 ? line : line.replace(new RegExp(`^ {0,${column}}`), ""))).join("\n");
    };
    const docOf = (node) => {
      const docs = node.jsDoc ?? [];
      return docs.length === 0 ? "" : commentText(text.slice(docs.at(-1).pos, docs.at(-1).end));
    };
    const nameOf = (node) => {
      if (node.name?.text) return node.name.text;
      if (node.kind === SyntaxKind.VariableStatement) return node.declarationList.declarations[0].name.text;
      return undefined;
    };
    const member = (node) => ({
      name: nameOf(node),
      kind: SyntaxKind[node.kind],
      doc: docOf(node),
      code: code(node),
      members: node.kind === SyntaxKind.PropertySignature && node.type?.kind === SyntaxKind.TypeLiteral ? node.type.members.map(member) : undefined,
    });

    const first = source.statements[0];
    const header = first && (first.jsDoc ?? []).length > 1 ? commentText(text.slice(first.jsDoc[0].pos, first.jsDoc[0].end)) : "";
    const declarations = [];
    const globals = [];
    for (const statement of source.statements) {
      if (statement.kind === SyntaxKind.ModuleDeclaration && nameOf(statement) === "global") {
        for (const inner of statement.body.statements) globals.push({ name: nameOf(inner), kind: SyntaxKind[inner.kind], doc: docOf(inner), code: code(inner) });
        continue;
      }
      declarations.push({
        name: nameOf(statement),
        kind: SyntaxKind[statement.kind],
        doc: docOf(statement),
        code: code(statement),
        members: statement.kind === SyntaxKind.InterfaceDeclaration ? statement.members.map(member) : undefined,
      });
    }
    return { header, declarations, globals };
  } finally {
    api.close();
  }
}

/** How api.md groups the top-level declarations; any declaration not named here goes under "Other types". */
const API_GROUPS = [
  ["What an extension exports", "`src/index.ts` exports any of `actions`, `detectors`, `captureRules` and `sources`, each an object keyed by the ids in manifest.json.",
    ["Actions", "Action", "Detectors", "Detector", "CaptureRules", "CaptureRule", "CaptureResult", "Sources", "Source", "SourceListing", "SourceRow",
      "SourceValue"]],
  ["What a call gets", "", ["Item", "Context", "ImageHandle"]],
  ["What a call returns", "", ["Result", "PreviewSection"]],
  ["The yab object", "The global `yab` is the extension's way to the app. Each part says when it works: some need a permission, and some work only in a run the person started or a source's `list` and `run` (not in hints, detectors, previews or capture rules).",
    ["Yab"]],
  ["Types used by yab", "", ["HistoryItem", "AIOptions", "TranslationResult", "HttpInit", "HttpResponse", "ExecOptions", "ExecResult"]],
  ["Errors", "Every code, with its cause and fix, is in [errors](errors.md#runtime-errors).", ["ExtensionErrorCode", "YabError"]],
];

function apiReference({ header, declarations, globals }) {
  const byName = new Map(declarations.map((declaration) => [declaration.name, declaration]));
  for (const [, , names] of API_GROUPS) {
    for (const name of names) if (!byName.has(name)) throw new Error(`tools/docs.mjs: index.d.ts no longer declares ${name}; update API_GROUPS`);
  }
  const grouped = new Set(API_GROUPS.flatMap(([, , names]) => names));
  const others = declarations.filter((declaration) => !grouped.has(declaration.name));
  const groups = [...API_GROUPS, ...(others.length > 0 ? [["Other types", "", others.map((declaration) => declaration.name)]] : [])];

  const block = (code) => ["```ts snippet", code, "```"];
  const paragraph = (text) => (text ? [text, ""] : []);
  const out = [];
  for (const [title, intro, names] of groups) {
    out.push(`## ${title}`, "", ...paragraph(intro));
    for (const name of names) {
      const declaration = byName.get(name);
      if (name === "Yab") {
        for (const part of declaration.members) {
          out.push(`### yab.${part.name}`, "", ...paragraph(part.doc));
          if (part.members) {
            for (const inner of part.members) {
              out.push(`#### yab.${part.name}.${inner.name}`, "", ...paragraph(inner.doc), ...block(inner.code), "");
            }
          } else out.push(...block(part.code), "");
        }
        continue;
      }
      out.push(`### ${name}`, "", ...paragraph(declaration.doc), ...block(declaration.code), "");
    }
  }
  out.push("## Globals", "", "Besides `yab`, these web standards are there. Anything else a browser or Node has is not: see [errors](errors.md#node-builtins).", "");
  for (const global of globals.filter((entry) => entry.name !== "yab")) {
    out.push(`### ${global.name}`, "", ...paragraph(global.doc), ...block(global.code), "");
  }

  const contents = groups.map(([title]) => title).concat("Globals")
    .map((title) => `[${title}](#${slug(title)})`).join(" · ");
  return [
    GENERATED_NOTE("packages/api/index.d.ts"),
    "",
    "# API reference",
    "",
    header,
    "",
    "In TypeScript, `import type { Actions, Item } from \"@yabbistir/api\";` brings these types in, and the globals come with them. The blocks below are the declarations as they are in `packages/api/index.d.ts`.",
    "",
    `Contents: ${contents}`,
    "",
    ...out,
  ].join("\n").replace(/\n{3,}/g, "\n\n");
}

// ---------------------------------------------------------------------------------------------------------------
// llms-full.txt

function llmsFull(root, generated) {
  const index = fs.readFileSync(path.join(root, "llms.txt"), "utf8");
  const main = index.split(/^## Optional\s*$/m)[0];
  const files = [];
  for (const { target } of linksOf(main)) {
    const file = target.split("#")[0];
    if (/^[a-z]+:/.test(file) || files.includes(file)) continue;
    files.push(file);
  }
  const parts = [
    "# yabbistir extensions: the full documentation",
    "",
    "Every document llms.txt lists, in its order, in one file. Generated by `npm run docs`; links between documents are relative to the repository's root folder or to the document's own folder.",
  ];
  for (const file of files) {
    const text = Object.hasOwn(generated, file) ? generated[file] : fs.readFileSync(path.join(root, file), "utf8");
    parts.push("", "", `${"=".repeat(80)}`, `File: ${file}`, `${"=".repeat(80)}`, "", text.trimEnd());
  }
  return `${parts.join("\n")}\n`;
}

// ---------------------------------------------------------------------------------------------------------------

function main(argv) {
  let root = fileURLToPath(new URL("..", import.meta.url));
  let check = false;
  for (let index = 0; index < argv.length; index++) {
    const argument = argv[index];
    if (argument === "--root") root = path.resolve(argv[++index] ?? ".");
    else if (argument === "--check") check = true;
    else if (argument === "--help" || argument === "-h") {
      console.log("Usage: npm run docs [-- --check]");
      return 0;
    } else {
      console.log(`Unknown argument: ${argument}. Usage: npm run docs [-- --check]`);
      return 2;
    }
  }

  const schema = JSON.parse(fs.readFileSync(path.join(root, "schema", "manifest.schema.json"), "utf8"));
  const example = fs.readFileSync(path.join(root, EXAMPLE_MANIFEST), "utf8");
  const generated = {
    "docs/manifest.md": manifestReference(schema, example),
    "docs/api.md": apiReference(readDeclarations(path.join(root, "packages", "api", "index.d.ts"))),
  };
  generated["llms-full.txt"] = llmsFull(root, generated);

  let stale = 0;
  for (const [file, text] of Object.entries(generated)) {
    const target = path.join(root, file);
    const current = fs.existsSync(target) ? fs.readFileSync(target, "utf8") : undefined;
    if (current === text) {
      console.log(`${file}: up to date`);
      continue;
    }
    if (check) {
      console.log(`${file}: out of date → fix: Run npm run docs and commit the result.`);
      stale++;
    } else {
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, text);
      console.log(`${file}: written`);
    }
  }
  return stale > 0 ? 1 : 0;
}

process.exitCode = main(process.argv.slice(2));
